-- ─── MANUAL DE CALAGEM E ADUBAÇÃO RS/SC — CQFS (2016) ───────────────────────
-- Recomendações de NPK para soja e milho no Sul do Brasil (RS/SC)
-- ─────────────────────────────────────────────────────────────────────────────

insert into public.conhecimento (titulo, tipo, cultura, conteudo, fonte, tags) values

('Manual Calagem RS/SC — Adubação de P e K para soja por nível de fertilidade',
 'protocolo', 'soja',
 'Recomendações de P₂O₅ e K₂O para soja no RS e SC segundo o Manual de Calagem e Adubação (2016), variando pelo nível de fertilidade do solo. FÓSFORO (kg P₂O₅/ha) — 1º cultivo / 2º cultivo: Muito baixo: 155 / 95; Baixo: 95 / 75; Médio: 85 / 45; Alto: 45 / 45; Muito alto: 0 / 45. POTÁSSIO (kg K₂O/ha) — 1º cultivo / 2º cultivo: Muito baixo: 155 / 115; Baixo: 115 / 95; Médio: 105 / 75; Alto: 75 / 75; Muito alto: 0 / ≥75. Ajuste por produtividade: para rendimento maior que 3 t/ha, acrescentar 15 kg P₂O₅/ha e 25 kg K₂O/ha por tonelada adicional de grãos a serem produzidos. Enxofre: se teor de S do solo < 10 mg S/kg, aplicar 20 kg S-SO₄/ha.',
 'CQFS RS/SC — Comissão de Química e Fertilidade do Solo (2016). Manual de Calagem e Adubação para os Estados do Rio Grande do Sul e de Santa Catarina. 11ª ed., SBCS/NRS.',
 '{soja, P, K, adubação, fertilidade, nível, recomendação, RS, SC, tabela}'),

('Manual Calagem RS/SC — N, Mo e Co para soja (inoculação e micronutrientes)',
 'protocolo', 'soja',
 'Nitrogênio: adubação nitrogenada NÃO é recomendada para soja devido à eficiência da FBN. A inoculação com Bradyrhizobium deve ser feita à sombra, com inoculante mantido a temperatura < 25°C. Não aplicar N mineral (inibe nodulação). Molibdênio: resposta em rendimento obtida em solos com pH < 5,5 com deficiência de N no início do desenvolvimento (amarelecimento foliar generalizado por baixa eficiência da FBN). Doses: 12-25 g Mo/ha via semente ou 25-50 g Mo/ha via foliar. Em solos arenosos, doses podem ser maiores. Fontes: molibdato de amônio (54% Mo) ou molibdato de sódio (39% Mo). ATENÇÃO: aplicação na semente deve preceder a inoculação. Aplicação foliar: entre 30 e 45 dias após a emergência. Monitorar: calagem que eleva pH aumenta disponibilidade de Mo — suspender aplicação ao solo quando teor na parte aérea atingir 5 mg Mo/kg (risco de molibdenose em ruminantes em ILP). Cobalto: não é essencial para soja, mas é para o rizóbio — dose máxima 3 g Co/ha (evitar fitotoxidez). Demais micronutrientes (Zn, Cu, Fe, Mn, B, Cl): somente em solos ou plantas com baixos teores confirmados.',
 'CQFS RS/SC — Comissão de Química e Fertilidade do Solo (2016). Manual de Calagem e Adubação para os Estados do Rio Grande do Sul e de Santa Catarina. 11ª ed., SBCS/NRS.',
 '{soja, N, FBN, inoculação, Mo, molibdênio, Co, cobalto, micronutrientes, pH, semente, foliar, RS, SC}'),

('Manual Calagem RS/SC — Adubação nitrogenada do milho por MO e cultura antecedente',
 'protocolo', 'milho',
 'Recomendação de N (kg/ha) para milho no RS e SC — semeadura + cobertura, por teor de matéria orgânica (MO%) e cultura antecedente: MO ≤ 2,5%: leguminosa=70, consórcio/pousio=80, gramínea=90. MO 2,6-5,0%: leguminosa=50, consórcio/pousio=60, gramínea=70. MO > 5,0%: ≤40 para todas as antecedentes. Para rendimento maior que 6 t/ha: +15 kg N/ha por tonelada adicional. Para densidade > 65.000 plantas/ha: +10 kg N/ha por incremento de 5.000 plantas/ha. Para rendimento > 10 t/ha: aumentar N em 20-40%. AJUSTES: alta biomassa de leguminosa (> 3 t MS/ha) = -20 kg N/ha; gramínea com alta biomassa (> 4 t MS/ha) = +20 a 40 kg N/ha. Rotação anual com soja: reduzir N em até 20%. APLICAÇÃO (plantio convencional): 10-30 kg N/ha na semeadura + restante em cobertura no estádio V4-V6 (40-60 cm de altura). APLICAÇÃO (plantio direto): 20-40 kg N/ha na semeadura em área com palhada de gramíneas; 10-20 kg na semeadura em área com leguminosas; cobertura antecipada em V3-V5. Fontes de N: sulfato de amônio e nitrato de amônio iguais ou superiores à ureia em condições desfavoráveis (pouca umidade, palha, altas temperaturas); em condições favoráveis (15-30 mm de chuva após aplicação), fontes equivalentes — usar a de menor custo.',
 'CQFS RS/SC — Comissão de Química e Fertilidade do Solo (2016). Manual de Calagem e Adubação para os Estados do Rio Grande do Sul e de Santa Catarina. 11ª ed., SBCS/NRS.',
 '{milho, N, nitrogênio, MO, matéria orgânica, cultura antecedente, cobertura, V4, V6, plantio direto, RS, SC}'),

('Manual Calagem RS/SC — Adubação de P e K para milho por nível de fertilidade',
 'protocolo', 'milho',
 'Recomendações de P₂O₅ e K₂O para milho no RS e SC segundo o Manual de Calagem e Adubação (2016). FÓSFORO (kg P₂O₅/ha) — 1º cultivo / 2º cultivo: Muito baixo: 200 / 140; Baixo: 140 / 120; Médio: 130 / 90; Alto: 90 / 90; Muito alto: 0 / ≥90. POTÁSSIO (kg K₂O/ha) — 1º cultivo / 2º cultivo: Muito baixo: 140 / 100; Baixo: 100 / 80; Médio: 90 / 60; Alto: 60 / 60; Muito alto: 0 / ≥60. Ajuste por produtividade: para rendimento maior que 6 t/ha, acrescentar 15 kg P₂O₅/ha e 10 kg K₂O/ha por tonelada adicional de grãos. Expectativa de rendimento: < 6 t/ha = solo/clima/manejo pouco favoráveis; ~6 t/ha = condições favoráveis sem irrigação; 6-8 t/ha = boas condições + eventual irrigação; > 8 t/ha = condições muito favoráveis + irrigação eficiente.',
 'CQFS RS/SC — Comissão de Química e Fertilidade do Solo (2016). Manual de Calagem e Adubação para os Estados do Rio Grande do Sul e de Santa Catarina. 11ª ed., SBCS/NRS.',
 '{milho, P, K, adubação, fertilidade, nível, recomendação, produtividade, RS, SC, tabela}');
